sys_ui_action.script:
function UpdateSelectedFunc() {
    var selectedTaskIds = g_list.getChecked(); //string of selected task's sys_ids from list
    if (!selectedTaskIds || selectedTaskIds.length == 0) {
        alert("No task is selected!");
        return;
	}

    var gajax = new GlideAjax("x_hsb11_hsbc_mss_t.MSS_Equities_UpdateTask_Utils");
    gajax.addParam("sysparm_name", "getStatesAndOutcomes");
    gajax.addParam("sysparm_taskIds", selectedTaskIds);
    gajax.getXMLAnswer(getReturnedResult);

    function getReturnedResult(response) {
        var returnedObj = JSON.parse(response);
		var outcomesArray = returnedObj.outcomesArray;
		var stateArray = returnedObj.stateArray;
        var taskNumberArray = returnedObj.taskNumberArray;

		var gdw = new GlideModal('UpdateSelectedTasks-Popup');  //The UI page has to be in "Global"
		//var gdw = new GlideModal('x_hsb11_hsbc_mss_t_UpdateSelectedTasks-Popup-TA');
    	gdw.setTitle('Update selected tasks');
    	//gdw.setSize("750", "1000");
		gdw.setSize('wide');
		gdw.setPreference('selectedTaskIds', selectedTaskIds);
		gdw.setPreference('taskNumberArray', taskNumberArray);
		gdw.setPreference('optionOutcomes', outcomesArray);
		gdw.setPreference('stateArray', JSON.stringify(stateArray));
    	gdw.render();
	}
}
